import time
import functools

def retry_call(fn, attempts, sleep):
    """
    Calls the given function until it succeeds, with a specified number of attempts and a sleep period between each attempt.

    Args:
        fn (function): The function to be called.
        attempts (int): The number of attempts to call the function.
        sleep (int): The number of seconds to sleep between each attempt.

    Returns:
        The result of the function call, or the last exception raised if all attempts fail.
    """
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        for _ in range(attempts):
            try:
                return fn(*args, **kwargs)
            except Exception as e:
                time.sleep(sleep)
        return e
    return wrapper
